// ═══════════════════════════════════════════════════════
// File filter
// ═══════════════════════════════════════════════════════
const FILTER_CATS = {
  // Extensions actually generated by DJI, Canon, Nikon, Panasonic, Fujifilm,
  // Blackmagic, RED, ARRI, Phantom (and Sony) cameras — not a generic media list.
  VIDEO:    { color:'var(--blue)',  exts:['mov','mp4','mxf','mts','m2ts','braw','r3d','ari','crm','nev','cine'] },
  AUDIO:    { color:'var(--pro)',   exts:['wav','m4a','mp3'] },
  PICTURES: { color:'var(--orange, #f2a33e)', exts:['jpg','jpeg','heic','hif','tif','tiff','dng','cr2','cr3','nef','raf','rw2','arw'] },
  OTHERS:   { color:'var(--text3)', exts:['xml','thm','cpi','bdm','mpl','rmd','lrf','srt','bnp','inp','int','db','dat'] },
};
function filterDefaults(){
  const f={};
  for (const [cat,def] of Object.entries(FILTER_CATS))
    for (const e of def.exts) f[e] = (cat!=='OTHERS');
  return f;
}
function onFileFilterToggle(el){
  S.fileFilter = el.checked;                    // session-only, never persisted
  if (S.fileFilter && !S.fileFilterFormats){    // first activation: defaults
    S.fileFilterFormats = filterDefaults();
    persistPrefs();
  }
  if (S.fileFilter) renderFilterList();
  updateSettingsDetails();
}
function renderFilterList(){
  const box=document.getElementById('ff-list');
  const F=S.fileFilterFormats;
  let h='';
  for (const [cat,def] of Object.entries(FILTER_CATS)){
    const states=def.exts.map(e=>!!F[e]);
    const allOn=states.every(Boolean), allOff=states.every(s=>!s);
    h+=`<div class="ff-cat">`+
       `<label class="switch"><input type="checkbox" aria-label="Copy every ${cat} file" ${allOn?'checked':''} data-cat="${cat}">`+
       `<span class="slider${(!allOn&&!allOff)?' ff-mixed':''}"></span></label>`+
       `<span class="ff-cat-name" style="color:${def.color};">${cat}</span></div>`;
    h+=`<div class="ff-fmts">`;
    for (const e of def.exts){
      h+=`<div class="ff-fmt"><label class="switch"><input type="checkbox" aria-label="Copy ${e.toUpperCase()} files" ${F[e]?'checked':''} data-ext="${e}"><span class="slider"></span></label>`+
         `<span class="ff-fmt-name">${e.toUpperCase()}</span></div>`;
    }
    h+=`</div>`;
  }
  box.innerHTML=h;
  for (const cb of box.querySelectorAll('input[data-cat]')) cb.onchange = function(){ toggleFilterCat(this.dataset.cat, this.checked); };
  for (const cb of box.querySelectorAll('input[data-ext]')) cb.onchange = function(){ toggleFilterExt(this.dataset.ext, this.checked); };
}
function toggleFilterExt(ext,on){
  S.fileFilterFormats[ext]=on;
  persistPrefs(); renderFilterList();
}
function toggleFilterCat(cat,on){
  for (const e of FILTER_CATS[cat].exts) S.fileFilterFormats[e]=on;
  persistPrefs(); renderFilterList();
}
function onFilterOpt(key,on){ S[key]=on; persistPrefs(); }
// Builds the option object passed to the copy engine; null when filter is off
function buildFileFilterOptions(){
  if (!S.fileFilter || !S.fileFilterFormats) return null;
  const extCat={};
  for (const [cat,def] of Object.entries(FILTER_CATS))
    for (const e of def.exts)
      if (S.fileFilterFormats[e]) extCat[e]=cat;
  return { extCat, copyEmpty:S.copyEmptyFolders, reorganize:S.reorganizeFiles };
}
function revealPath(p){ try{ window.ingesto.revealPath(p); }catch(_){} }
function revealAt(i){ const p=(S._revealPaths||[])[i]; if(p) revealPath(p); }
